{
  "name": "Thorlabs DC4100 多通道 LED 控制器",
  "name_en": "Thorlabs DC4100 Multi-Channel LED Controller",
  "manufacturer": "Thorlabs",
  "description": "用于控制多通道 LED 照明的实验室光源控制器，可连接设备、切换各通道开关、设置和读取亮度，并查询序列号、固件和制造商信息。适用于显微成像或其他实验照明场景中的 LED 光源管理。",
  "description_en": "A laboratory multi-channel LED illumination controller used to manage LED light sources. It supports connecting to the device, switching individual channels on or off, setting and reading brightness, and querying serial number, firmware, and manufacturer information. It is suitable for microscopy and other experimental illumination applications.",
  "actions": [
    {
      "action_name": "auto-connect_device",
      "description": "连接 DC4100 控制器。",
      "description_en": "Connect to the DC4100 controller."
    },
    {
      "action_name": "auto-set_led_channel_state",
      "description": "设置指定 LED 通道的开关状态。",
      "description_en": "Set the on/off state of the specified LED channel."
    },
    {
      "action_name": "auto-led_on",
      "description": "打开指定 LED 通道。",
      "description_en": "Turn on the specified LED channel."
    },
    {
      "action_name": "auto-led_off",
      "description": "关闭指定 LED 通道。",
      "description_en": "Turn off the specified LED channel."
    },
    {
      "action_name": "auto-set_brightness",
      "description": "设置指定 LED 通道的亮度。",
      "description_en": "Set the brightness of the specified LED channel."
    },
    {
      "action_name": "auto-get_brightness",
      "description": "获取指定 LED 通道的亮度。",
      "description_en": "Get the brightness of the specified LED channel."
    },
    {
      "action_name": "auto-check_if_on",
      "description": "检查指定 LED 通道是否开启。",
      "description_en": "Check whether the specified LED channel is on."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取设备序列号。",
      "description_en": "Get the device serial number."
    },
    {
      "action_name": "auto-firmware",
      "description": "获取固件版本信息。",
      "description_en": "Get the firmware version information."
    },
    {
      "action_name": "auto-manufacturer",
      "description": "获取制造商信息。",
      "description_en": "Get the manufacturer information."
    }
  ],
  "tag_hints": [
    "LED illumination control",
    "multi-channel LED controller",
    "brightness control",
    "channel on/off switching",
    "microscopy illumination",
    "Thorlabs DC4100"
  ]
}

